using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // The MCP SDK creates a new instance per tool invocation via DI.
    // Constructor parameters are resolved from the service container,
    // so HttpClient here comes from the named IHttpClientFactory registration.
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool(Name = "get_forecast")]
    [Description("Get the weather forecast for a city. Returns temperature and conditions.")]
    public async Task<string> GetForecast(
        [Description("City name, e.g. 'Seattle'")] string city,
        [Description("Unit: 'metric' or 'imperial' (default: metric)")] string units = "metric")
    {
        try
        {
            // Example REST API call — replace with your real endpoint
            var response = await _httpClient.GetAsync(
                $"/weather?city={Uri.EscapeDataString(city)}&units={Uri.EscapeDataString(units)}");

            response.EnsureSuccessStatusCode();

            var weather = await response.Content.ReadFromJsonAsync<WeatherResponse>();
            return $"{city}: {weather?.Temperature}° ({weather?.Conditions})";
        }
        catch (HttpRequestException ex)
        {
            return $"Error fetching weather for '{city}': {ex.Message}";
        }
    }

    [McpServerTool(Name = "get_alerts")]
    [Description("Get active weather alerts for a US state by two-letter code.")]
    public async Task<string> GetAlerts(
        [Description("Two-letter US state code, e.g. 'WA'")] string state)
    {
        try
        {
            var response = await _httpClient.GetAsync(
                $"/alerts?state={Uri.EscapeDataString(state)}");

            response.EnsureSuccessStatusCode();

            var alerts = await response.Content.ReadFromJsonAsync<AlertResponse[]>();
            if (alerts is null || alerts.Length == 0)
                return $"No active alerts for {state}.";

            return string.Join("\n", alerts.Select(a => $"⚠ {a.Event}: {a.Headline}"));
        }
        catch (HttpRequestException ex)
        {
            return $"Error fetching alerts for '{state}': {ex.Message}";
        }
    }
}

// DTOs for the REST API responses
public record WeatherResponse(
    [property: JsonPropertyName("temperature")] double Temperature,
    [property: JsonPropertyName("conditions")] string Conditions);

public record AlertResponse(
    [property: JsonPropertyName("event")] string Event,
    [property: JsonPropertyName("headline")] string Headline);

